// Helpers
const getPlayerLastRealAttendance = (playerId: string, playerName: string, sessions: Session[]) => {
  let lastDate: string | null = null;
  sessions.forEach(session => {
    const attendee = session.attendees.find(a => a.playerId === playerId || a.name === playerName);
    if (attendee && isAttendeePresent(attendee)) {
      if (!lastDate || new Date(session.date || 0) > new Date(lastDate)) {
        lastDate = session.date || null;
      }
    }
  });
  return lastDate;
};

const getMonthKey = (date: Date | string): string => {
  const d = new Date(date);
  const year = d.getFullYear();
  const month = String(d.getMonth() + 1).padStart(2, '0');
  return `${year}-${month}`;
};

const getMonthDifference = (fromKey: string, toKey: string): number => {
  const [fY, fM] = fromKey.split('-').map(Number);
  const [tY, tM] = toKey.split('-').map(Number);
  return (tY - fY) * 12 + (tM - fM);
};

const getMonthRange = (startMonthKey: string, count: number): string[] => {
  const [year, month] = startMonthKey.split('-').map(Number);
  const range: string[] = [];
  for (let i = 0; i < count; i++) {
    const date = new Date(year, month - 1 + i, 1);
    range.push(getMonthKey(date));
  }
  return range;
};

const createDefaultPointsProfile = (): PointsProfile => ({
  totalPoints: 0,
  currentMonthPoints: 0,
  pointsHistory: [],
  penaltyMode: 'none'
});

const createDefaultMonthlySubscription = (monthKey: string): MonthlySubscription => ({
  id: crypto.randomUUID(),
  monthKey,
  status: 'pending',
  pointsAwarded: 0,
  autoGenerated: true
});

const getMonthLabel = (monthKey: string): string => {
  const [year, month] = monthKey.split('-');
  const date = new Date(parseInt(year), parseInt(month) - 1);
  return date.toLocaleDateString('ar-EG', { month: 'long', year: 'numeric' });
};

const getMonthlySubscriptionReview = (monthKey: string, players: Player[], manuallyExcludedIds: string[] = []) => {
  const included: { player: Player; reason?: string }[] = [];
  const excluded: { player: Player; reason: string }[] = [];

  players.forEach(player => {
    if (player.isDeleted) {
      return;
    }

    // Manual exclusion check first
    if (manuallyExcludedIds.includes(player.id)) {
      excluded.push({ player, reason: 'مستثنى يدوياً لهذا الشهر' });
      return;
    }

    if (player.isExcused) {
      excluded.push({ player, reason: 'متوقف لعذر' });
      return;
    }
    if (player.subscriptionTrackingMode === 'paused') {
      excluded.push({ player, reason: 'إيقاف مؤقت' });
      return;
    }
    const now = new Date();
    const currentMonthReview = getMonthKey(now);
    const penaltyPreviewReview = getSubscriptionPenaltyPreview(player, currentMonthReview);
    if (penaltyPreviewReview.status === 'suspended_candidate') {
      excluded.push({ player, reason: 'موقوف القيد' });
      return;
    }
    if (player.pointsProfile.penaltyMode === 'suspended') {
      excluded.push({ player, reason: 'توقيف القيد' });
      return;
    }
    const hasSub = player.monthlySubscriptions.some(s => s.monthKey === monthKey);
    if (hasSub) {
      excluded.push({ player, reason: 'تم تسجيل اشتراك هذا الشهر مسبقاً' });
      return;
    }

    included.push({ player });
  });

  return { included, excluded };
};

const normalizePlayer = (data: any, id: string): Player => {
  return {
    id,
    name: data.name,
    debt: data.debt || 0,
    weeklyDebt: data.weeklyDebt || data.debt || 0,
    monthlyDebt: data.monthlyDebt || 0,
    debtHistory: data.debtHistory || [],
    isDeleted: data.isDeleted || false,
    isExcused: data.isExcused || false,
    pointsProfile: data.pointsProfile || createDefaultPointsProfile(),
    monthlySubscriptions: data.monthlySubscriptions || [],
    subscriptionTrackingMode: data.subscriptionTrackingMode || 'auto',
    lastFollowUpDate: data.lastFollowUpDate,
    createdAt: data.createdAt
  };
};

const getSubscriptionMonthState = (player: Player | undefined, monthKey: string) => {
  if (!player) return { isPaid: false, matchingDebt: undefined, canCopyInvoice: false };

  const debtsForMonth = player.debtHistory?.filter(d => 
    d.type === 'monthly' && 
    (d.monthKey === monthKey || d.subscriptionMonthKey === monthKey)
  ) || [];

  const activePaidDebt = debtsForMonth.find(d => 
    d.isPaid === true && 
    d.isVoided !== true && 
    !d.voidedAt &&
    d.paymentStatus !== 'cancelled'
  );

  const voidedDebtForMonth = debtsForMonth.find(d => 
    d.isVoided === true || 
    !!d.voidedAt ||
    d.paymentStatus === 'cancelled'
  );

  const subscription = player.monthlySubscriptions?.find(s => s.monthKey === monthKey);

  if (activePaidDebt) {
    return {
      isPaid: true,
      matchingDebt: activePaidDebt,
      canCopyInvoice: true
    };
  } else if (voidedDebtForMonth) {
    return {
      isPaid: false,
      matchingDebt: undefined,
      canCopyInvoice: false
    };
  } else if (subscription?.status === 'paid' && !subscription.paymentVoided && !subscription.voidedAt) {
    // Legacy paid subscription without a debt
    return {
      isPaid: true,
      matchingDebt: undefined,
      canCopyInvoice: false
    };
  }

  return {
    isPaid: false,
    matchingDebt: undefined,
    canCopyInvoice: false
  };
};

const getMonthlySubscriptionBonusEffectiveDate = (subscriptionMonthKey: string, paidDate: string): string | undefined => {
  if (!paidDate || !subscriptionMonthKey) return undefined;
  
  const [year, month] = subscriptionMonthKey.split('-').map(Number);
  const subscriptionStart = new Date(year, month - 1, 1);
  const nextMonthStart = new Date(year, month, 1);
  
  const [pYear, pMonth, pDay] = paidDate.split('T')[0].split('-').map(Number);
  const paid = new Date(pYear, pMonth - 1, pDay);
  
  if (paid < subscriptionStart) {
    // Paid before month, points apply on the first of the month
    return subscriptionStart.toISOString().split('T')[0];
  }
  if (paid >= subscriptionStart && paid < nextMonthStart) {
    // Paid inside the month, points apply immediately
    return paidDate.split('T')[0];
  }
  return undefined;
};

const getMonthlySubscriptionBonusPoints = (subscriptionMonthKey: string, paidDate: string): number => {
  const [pYear, pMonth, pDay] = paidDate.split('T')[0].split('-').map(Number);
  const paid = new Date(pYear, pMonth - 1, pDay);
  
  const [year, month] = subscriptionMonthKey.split('-').map(Number);
  
  const subscriptionStart = new Date(year, month - 1, 1);
  const nextMonthStart = new Date(year, month, 1);

  if (paid < subscriptionStart) return 5;

  if (paid >= subscriptionStart && paid < nextMonthStart) {
    const day = paid.getDate();
    if (day <= 5) return 5;
    if (day <= 10) return 4;
    if (day <= 15) return 3;
    return 2;
  }
  
  return 0;
};

const generateReceiptText = ({
  template,
  playerName,
  amount,
  paidDate,
  serialStr
}: {
  template: string;
  playerName: string;
  amount: number | string;
  paidDate: string;
  serialStr: string;
}) => {
  let text = template
    .replace(/{name}/g, playerName)
    .replace(/{amount}/g, String(amount))
    .replace(/{date}/g, paidDate)
    .replace(/{serial}/g, serialStr);
  
  // Clean up if template didn't have {serial} but hardcoded "رقم السند: -"
  text = text.replace(/رقم السند:\s*-/, `رقم السند: ${serialStr}`);
  
  // Final safeguard: if serial still not in text, append it
  if (!text.includes(serialStr)) {
    text += `\nرقم السند: ${serialStr}`;
  }
  return text;
};

interface PenaltyPreview {
  status: 'none' | 'half_points_candidate' | 'suspended_candidate' | 'exempt_excused' | 'exempt_paused';
  overdueMonthKeys: string[];
  oldestUnpaidMonthKey?: string;
  monthsOverdueCount: number;
  reason?: string;
}

const getSubscriptionPenaltyPreview = (player: Player, currentMonthKey: string): PenaltyPreview => {
  if (player.isDeleted) return { status: 'none', overdueMonthKeys: [], monthsOverdueCount: 0 };
  if (player.isExcused) return { status: 'exempt_excused', overdueMonthKeys: [], monthsOverdueCount: 0, reason: 'متوقف لعذر' };
  if (player.subscriptionTrackingMode === 'paused') return { status: 'exempt_paused', overdueMonthKeys: [], monthsOverdueCount: 0, reason: 'إيقاف مؤقت' };

  const unpaidSubs = player.monthlySubscriptions
    .filter(s => s.status !== 'paid' && s.status !== 'paused' && s.status !== 'suspended')
    .sort((a, b) => a.monthKey.localeCompare(b.monthKey));

  if (unpaidSubs.length === 0) {
    return { status: 'none', overdueMonthKeys: [], monthsOverdueCount: 0 };
  }

  const overdueMonthKeys = unpaidSubs
    .map(s => s.monthKey)
    .filter(monthKey => monthKey < currentMonthKey);

  if (overdueMonthKeys.length === 0) {
    return { status: 'none', overdueMonthKeys: [], monthsOverdueCount: 0 };
  }

  const oldestUnpaid = overdueMonthKeys[0];
  const diff = getMonthDifference(oldestUnpaid, currentMonthKey);

  let status: PenaltyPreview['status'] = 'none';
  let reason = '';

  if (diff >= 3) {
    status = 'suspended_candidate';
    reason = `مرشح لتوقيف القيد بسبب ${getMonthLabel(oldestUnpaid)}`;
  } else if (diff >= 2) {
    status = 'half_points_candidate';
    reason = `مرشح لخصم 50% بسبب ${getMonthLabel(oldestUnpaid)}`;
  } else {
    status = 'none';
    reason = `متأخر في ${getMonthLabel(oldestUnpaid)}`;
  }

  return {
    status,
    overdueMonthKeys,
    oldestUnpaidMonthKey: oldestUnpaid,
    monthsOverdueCount: overdueMonthKeys.length,
    reason
  };
};

const getCurrentPenaltyMode = (player: Player, now: Date): 'none' | 'half_points' | 'suspended' => {
  if (player.subscriptionTrackingMode === 'paused') return 'none';
  
  const currentMonth = new Date(now.getFullYear(), now.getMonth(), 1);
  const prevMonth = new Date(now.getFullYear(), now.getMonth() - 1, 1);
  const prevMonthKey = getMonthKey(prevMonth);
  
  // Find unpaid subscriptions
  const unpaidSubs = player.monthlySubscriptions.filter(s => s.status !== 'paid');
  
  if (unpaidSubs.length === 0) return 'none';
  
  // Check if there's an unpaid sub for prev month or older
  const olderThanPrev = unpaidSubs.some(s => {
    const subDate = new Date(s.monthKey + '-01');
    return subDate < prevMonth;
  });
  
  if (olderThanPrev) return 'suspended';
  
  const hasPrevMonthUnpaid = unpaidSubs.some(s => s.monthKey === prevMonthKey);
  if (hasPrevMonthUnpaid) return 'half_points';
  
  return 'none';
};

