  const handleCopyInvoice = async (playerId: string, debtId: string) => {
    if (!user) return;
    const player = players.find(p => p.id === playerId);
    if (!player || !player.debtHistory) return;
    const debt = player.debtHistory.find(d => d.id === debtId);
    if (!debt || !debt.isPaid) return;

    let invoiceText = debt.invoiceText;
    let receiptNumber = debt.receiptNumber;

    if (!invoiceText || !receiptNumber) {
      // Archive serial for old unrecorded invoices
      receiptNumber = receiptNumber || `ARCH-${new Date(debt.date || debt.createdAt || new Date()).getFullYear()}${(new Date(debt.date || debt.createdAt || new Date()).getMonth() + 1).toString().padStart(2, '0')}-${debt.id.slice(-4).toUpperCase()}`;

      invoiceText = generateReceiptText({
        template: userSettings.receiptTemplate,
        playerName: player.name,
        amount: debt.amount,
        paidDate: debt.paidDate || new Date().toISOString().split('T')[0],
        serialStr: receiptNumber
      });
        
      const updatedHistory = player.debtHistory.map(d => 
        d.id === debtId ? { ...d, invoiceText, receiptNumber } : d
      );
      
      try {
        await updateDoc(doc(db, `users/${user.uid}/players/${playerId}`), {
          debtHistory: updatedHistory,
        });
      } catch (err) {
        handleFirestoreError(err, OperationType.UPDATE, `users/${user.uid}/players/${playerId}`);
      }
    }

    try {
      await navigator.clipboard.writeText(invoiceText);
      showToast('تم نسخ السند بنجاح');
    } catch (err) {
      console.error('Failed to copy text: ', err);
      showToast('تعذر نسخ السند عبر المتصفح');
    }
  };

  const handleRecordMonthlyPayment = async (playerId: string, monthKeys: string[], paymentDate: string, method: 'cash' | 'transfer', note: string) => {
    if (!user) return;
    const player = players.find(p => p.id === playerId);
    if (!player) return;

    const subFee = userSettings.financialSettings?.monthlySubFee || 0;
    
    try {
      let currentMonthlyDebt = player.monthlyDebt || 0;
      let currentDebtHistory = [...(player.debtHistory || [])];
      let currentSubscriptions = [...(player.monthlySubscriptions || [])];
      
      const results = {
        success: 0,
        skipped: 0
      };

      monthKeys.forEach(monthKey => {
        const existingSubIndex = currentSubscriptions.findIndex(s => s.monthKey === monthKey);
        const existingSub = existingSubIndex !== -1 ? currentSubscriptions[existingSubIndex] : null;

        if (existingSub && existingSub.status === 'paid') {
          results.skipped++;
          return;
        }

        const points = getMonthlySubscriptionBonusPoints(monthKey, paymentDate);
        const bonusReason = points === 5 ? 'prepaid_before_month_start' : 'paid_within_month';

        // Update or create subscription
        if (existingSub) {
          currentSubscriptions[existingSubIndex] = {
            ...existingSub,
            status: 'paid',
            paidDate: paymentDate,
            pointsAwarded: points,
            note: (existingSub.note ? existingSub.note + " | " : "") + `تم السداد يدوياً (${note})`
          };
        } else {
          currentSubscriptions.push({
            id: crypto.randomUUID(),
            monthKey,
            status: 'paid',
            paidDate: paymentDate,
            autoGenerated: false,
            pointsAwarded: points,
            note: `تم السداد يدوياً (${note})`
          });
        }
        
        if (points > 0) {
          if (!player.pointsProfile) player.pointsProfile = createDefaultPointsProfile();
          if (!player.pointsProfile.pointsHistory) player.pointsProfile.pointsHistory = [];
          
          const alreadyAwarded = player.pointsProfile.pointsHistory.some(t => 
            t.sourceType === 'monthly_subscription_bonus' && 
            t.metadata?.subscriptionMonthKey === monthKey
          );

          if (!alreadyAwarded) {
            const effectiveDate = getMonthlySubscriptionBonusEffectiveDate(monthKey, paymentDate) || paymentDate;
            const transaction: PointsTransaction = {
              id: crypto.randomUUID(),
              date: effectiveDate,
              monthKey: monthKey,
              points: points,
              sourceType: 'monthly_subscription_bonus',
              mode: 'normal',
              note: points === 5 ? 'سداد قبل دخول شهر الاشتراك' : 'سداد داخل شهر الاشتراك',
              metadata: {
                subscriptionMonthKey: monthKey,
                paidDate: paymentDate,
                effectiveDate,
                paymentMethod: method,
                reason: bonusReason
              }
            };
            player.pointsProfile.pointsHistory.push(transaction);
          }
        }

        // Handle DebtRecord
        let debtRef: DebtRecord;
        const unpaidDebtIndex = currentDebtHistory.findIndex(d => d.monthKey === monthKey && d.type === 'monthly' && !d.isPaid);
        if (unpaidDebtIndex !== -1) {
          currentDebtHistory[unpaidDebtIndex] = {
            ...currentDebtHistory[unpaidDebtIndex],
            isPaid: true,
            paidDate: paymentDate,
            paymentMethod: method,
            note: (currentDebtHistory[unpaidDebtIndex].note ? currentDebtHistory[unpaidDebtIndex].note + " | " : "") + `سداد يدوي: ${note}`
          };
          debtRef = currentDebtHistory[unpaidDebtIndex];
          // Decrease debt only if it was an actual unpaid debt
          currentMonthlyDebt = Math.max(0, currentMonthlyDebt - subFee);
        } else {
          // If no unpaid debt record exists for this month, we still record the payment in subscriptions
          // but we don't subtract from monthlyDebt to avoid negative balances
          const newDebt: DebtRecord = {
            id: crypto.randomUUID(),
            amount: subFee,
            type: 'monthly',
            date: paymentDate,
            createdAt: new Date().toISOString(),
            isPaid: true,
            paidDate: paymentDate,
            paymentMethod: method,
            monthKey,
            source: 'manual_advance_payment',
            note: `سداد مقدم: ${note}`
          };
          currentDebtHistory.push(newDebt);
          debtRef = newDebt;
        }

        // Generate receipt
        const nextSerial = (userSettings.nextSerial || 1) + results.success;
        const serialStr = String(nextSerial).padStart(4, '0');
        debtRef.receiptNumber = serialStr;
        debtRef.invoiceText = generateReceiptText({
          template: userSettings.receiptTemplate,
          playerName: player.name,
          amount: debtRef.amount,
          paidDate: paymentDate,
          serialStr
        });

        // Link subscription to debt
        const updatedSubIndex = currentSubscriptions.findIndex(s => s.monthKey === monthKey);
        if (updatedSubIndex !== -1) {
          currentSubscriptions[updatedSubIndex].paymentDebtId = debtRef.id;
          currentSubscriptions[updatedSubIndex].receiptNumber = serialStr;
          currentSubscriptions[updatedSubIndex].paymentVoided = false;
        }
        
        results.success++;
      });

      if (results.success > 0) {
        const playerPath = `users/${user.uid}/players/${player.id}`;
        const newNextSerial = (userSettings.nextSerial || 1) + results.success;
        
        await updateDoc(doc(db, playerPath), {
          monthlyDebt: currentMonthlyDebt,
          debtHistory: currentDebtHistory,
          monthlySubscriptions: currentSubscriptions,
          pointsProfile: player.pointsProfile
        });
        
        await setDoc(doc(db, `users/${user.uid}`), {
          nextSerial: newNextSerial
        }, { merge: true });
        
        showToast(`تم تسجيل سداد ${results.success} شهر بنجاح. تم إنشاء الأسناد. ` + (results.skipped > 0 ? ` (تم تخطي ${results.skipped} شهر مدفوع مسبقاً)` : ''));
        setUserSettings(prev => ({ ...prev, nextSerial: newNextSerial }));
        setModal('none');
      } else if (results.skipped > 0) {
        showToast(`الأشهر المختارة مدفوعة مسبقاً بالفعل`);
      }

    } catch (error) {
      handleFirestoreError(error, OperationType.UPDATE, `users/${user.uid}/players/${playerId}`);
    }
  };

