  const generateCompetitionRounds = (start: string, end: string, day: number) => {
    if (!start || !end) return [];
    const startDate = new Date(start);
    const endDate = new Date(end);
    const rounds: CompetitionRound[] = [];
    let current = new Date(startDate);
    
    // Find first occurrence of 'day'
    while (current.getDay() !== day && current <= endDate) {
      current.setDate(current.getDate() + 1);
    }
    
    let count = 1;
    while (current <= endDate) {
      rounds.push({
        id: crypto.randomUUID(),
        number: count++,
        date: current.toISOString().split('T')[0],
        status: current > new Date() ? 'upcoming' : 'active',
        points: {},
        excludedPlayerIds: [],
        normalCreditSnapshot: {},
        totalWeightedScores: {}
      });
      current.setDate(current.getDate() + 7);
    }
    return rounds;
  };

  const handleSaveCompetitionSettings = async (isEnabled: boolean) => {
    if (!user) return;
    if (isEnabled && (!compTitle || !compStart || !compEnd)) {
      showToast('يرجى إكمال بيانات المسابقة الأساسية');
      return;
    }

    const path = `users/${user.uid}`;
    
    // Manage rounds count
    let updatedRounds = [...localRounds];
    
    if (isEnabled) {
      if (compAutoGenerateRounds) {
        const generated = generateCompetitionRounds(compStart, compEnd, compWeekDay);
        // We want to preserve points/data for rounds that already exist if the dates/numbers match
        updatedRounds = generated.map(gr => {
           const existing = updatedRounds.find(er => er.date === gr.date);
           if (existing) return { 
             ...gr, 
             ...existing, 
             status: (existing.status === 'cancelled') ? 'cancelled' : gr.status 
           };
           return gr;
        });
      } else {
        if (updatedRounds.length < compRoundsCount) {
          for (let i = updatedRounds.length; i < compRoundsCount; i++) {
            updatedRounds.push({
              id: crypto.randomUUID(),
              number: i + 1,
              date: '',
              status: 'upcoming',
              points: {},
              excludedPlayerIds: [],
              normalCreditSnapshot: {},
              totalWeightedScores: {}
            });
          }
        } else if (updatedRounds.length > compRoundsCount) {
          updatedRounds = updatedRounds.slice(0, compRoundsCount);
        }
      }
    }

    const settings: CompetitionSettings = {
      isEnabled,
      status: compStatus || 'active',
      title: compTitle || '',
      startDate: compStart || '',
      endDate: compEnd || '',
      weekDay: compWeekDay,
      autoGenerateRounds: compAutoGenerateRounds,
      transformType: 'divide_and_floor',
      divisor: Math.max(1, Number(compDivisor) || 2),
      votesPerPoint: Math.max(1, Number(compDivisor) || 2),
      weight: 20,
      normalCreditType: compNormalCreditType,
      customRange: compNormalCreditType === 'custom' ? { from: compCustomStart || '', to: compCustomEnd || '' } : null as any,
      initialParticipantIds: compInitialPlayers || [],
      rounds: updatedRounds.map(r => {
        const newPoints = { ...r.points };
        Object.keys(newPoints).forEach(pid => {
           if (!compInitialPlayers.includes(pid)) delete newPoints[pid];
        });
        
        // Calculate fresh normal credit snapshot values for each active player
        const newSnapshot: Record<string, number> = {};
        compInitialPlayers.forEach(pid => {
          const player = players.find(p => p.id === pid);
          if (player) {
            // Create a temp settings object to use with our centralized calculation function
            const tempSettings: any = {
              normalCreditType: compNormalCreditType,
              startDate: compStart,
              endDate: compEnd,
              customRange: compNormalCreditType === 'custom' ? { from: compCustomStart || '', to: compCustomEnd || '' } : null
            };
            newSnapshot[pid] = getCompetitionNormalCredit(player, tempSettings, r.date);
          }
        });

        const newWeighted = { ...(r.totalWeightedScores || {}) };
        Object.keys(newWeighted).forEach(pid => {
           if (!compInitialPlayers.includes(pid)) delete newWeighted[pid];
        });

        return {
          ...r,
          points: newPoints,
          normalCreditSnapshot: newSnapshot,
          totalWeightedScores: newWeighted,
          excludedPlayerIds: (r.excludedPlayerIds || []).filter(id => compInitialPlayers.includes(id)),
          nonVoterPlayerIds: (r.nonVoterPlayerIds || []).filter(id => compInitialPlayers.includes(id)),
          subscriptionDebtPlayerIds: (r.subscriptionDebtPlayerIds || []).filter(id => compInitialPlayers.includes(id)),
          status: r.status === 'cancelled' ? 'cancelled' : 
                  (r.date && new Date(r.date) < new Date() ? 
                  (Object.keys(newPoints).length > 0 ? 'completed' : 'active') : 'upcoming')
        };
      }),
      updatedAt: new Date().toISOString()
    };
    
    // Optimistic UI update
    setUserSettings(prev => ({
      ...prev,
      competitionSettings: settings
    }));
    
    try {
      await setDoc(doc(db, path), {
        competitionSettings: settings
      }, { merge: true });
      showToast(isEnabled ? 'تم حفظ إعدادات المسابقة' : 'تم إيقاف وضع المسابقة مؤقتاً');
      setModal('none');
    } catch (error) {
      handleFirestoreError(error, OperationType.UPDATE, path);
    }
  };

