  const handleReactivatePlayer = async (keepDebt: boolean) => {
    if (!user || !modalData) return;
    const path = `users/${user.uid}/players/${modalData}`;
    try {
      const player = players.find(p => p.id === modalData);
      if (player) {
         let updates: any = {
           isDeleted: false,
           membershipStatus: 'active',
           terminationSnapshot: deleteField()
         };

         if (!keepDebt) {
            // Settle previous debts
            updates.weeklyDebt = 0;
            updates.monthlyDebt = 0;
            
            // Add settlement note to history if there was debt
            if ((player.weeklyDebt || 0) > 0 || (player.monthlyDebt || 0) > 0) {
               const newRecord: DebtRecord = {
                 id: Date.now().toString(),
                 type: 'weekly', // Generic settlement type
                 amount: (player.weeklyDebt || 0) + (player.monthlyDebt || 0),
                 date: new Date().toISOString(),
                 isPaid: true,
                 paidDate: new Date().toISOString(),
                 createdAt: new Date().toISOString(),
                 note: 'تسوية المديونية السابقة عند إعادة التفعيل'
               };
               updates.debtHistory = [...(player.debtHistory || []), newRecord];
               
               // Mark monthly subs as paid/settled
               updates.monthlySubscriptions = (player.monthlySubscriptions || []).map(s => {
                  if (s.status !== 'paid') {
                     return { ...s, status: 'paid', paidDate: new Date().toISOString() };
                  }
                  return s;
               });
            }
         }
         
         await updateDoc(doc(db, path), updates);
         showToast('تمت إعادة تفعيل اللاعب بنجاح');
      }
      setModal('none');
    } catch (error) {
      handleFirestoreError(error, OperationType.UPDATE, path);
    }
  };

  const removePlayer = async () => {
    if (!user || !modalData) return;
    const path = `users/${user.uid}/players/${modalData}`;
    try {
      const player = players.find(p => p.id === modalData);
      if (player) {
        await updateDoc(doc(db, path), {
          isDeleted: true,
          membershipStatus: 'terminated',
          terminationSnapshot: {
            weeklyDebt: player.weeklyDebt || 0,
            monthlyDebt: player.monthlyDebt || 0,
            totalDebt: (player.weeklyDebt || 0) + (player.monthlyDebt || 0) + (player.debt || 0),
            debtHistory: player.debtHistory || [],
            monthlySubscriptions: player.monthlySubscriptions || [],
            lastAppearance: getPlayerLastRealAttendance(player.id, player.name, sessions) || '',
            terminatedAt: new Date().toISOString()
          }
        });
      }
      
      // Remove associated attendee if exists
      const attendeeToRemove = attendees.find(a => a.playerId === modalData);
      if (attendeeToRemove) {
        const attendeePath = `users/${user.uid}/attendees/${attendeeToRemove.id}`;
        await deleteDoc(doc(db, attendeePath));
      }

      // Cleanup competition data
      if (userSettings.competitionSettings?.title) {
         const comp = userSettings.competitionSettings;
         if (comp.initialParticipantIds?.includes(modalData)) {
            const newParticipantIds = comp.initialParticipantIds.filter(id => id !== modalData);
            const newRounds = (comp.rounds || []).map(r => {
               const newPoints = { ...r.points };
               if (newPoints[modalData]) delete newPoints[modalData];
               
               const cloneSnapshot = { ...(r.normalCreditSnapshot || {}) };
               if (cloneSnapshot[modalData]) delete cloneSnapshot[modalData];
               
               const cloneWeighted = { ...(r.totalWeightedScores || {}) };
               if (cloneWeighted[modalData]) delete cloneWeighted[modalData];
               
               return {
                  ...r,
                  points: newPoints,
                  excludedPlayerIds: (r.excludedPlayerIds || []).filter(id => id !== modalData),
                  nonVoterPlayerIds: (r.nonVoterPlayerIds || []).filter(id => id !== modalData),
                  subscriptionDebtPlayerIds: (r.subscriptionDebtPlayerIds || []).filter(id => id !== modalData),
                  normalCreditSnapshot: cloneSnapshot,
                  totalWeightedScores: cloneWeighted
               };
            });
            
            await updateDoc(doc(db, `users/${user.uid}`), {
               'competitionSettings.initialParticipantIds': newParticipantIds,
               'competitionSettings.rounds': newRounds
            });
         }
      }

      setModal('none');
    } catch (error) {
      handleFirestoreError(error, OperationType.UPDATE, path);
    }
  };

