  const saveSessionEdit = async () => {
    if (!user || !editingSession || !editingSession.title.trim()) return;
    const path = `users/${user.uid}/sessions/${editingSession.id}`;
    
    try {
      const cost = parseInt(sessionCost) || 0;
      const presentCountForRevenue = editingSession.attendees.filter(isAttendeePresent).length;
      const expectedRev = presentCountForRevenue * cost;
      const computedTotalExpenses = sessionExpenseItems.reduce((acc, item) => acc + (Number(item.amount) || 0), 0);
      const computedNet = expectedRev - computedTotalExpenses;

      await updateDoc(doc(db, path), {
        title: editingSession.title.trim(),
        date: editingSession.date || '',
        attendees: editingSession.attendees,
        expenses: sessionExpenseItems,
        totalExpenses: computedTotalExpenses,
        expectedRevenue: expectedRev,
        netForBox: computedNet,
        sessionCost: cost
      });

      // Sync financial transactions with updated data
      await syncSessionTransactions(editingSession.id, {
        title: editingSession.title.trim(),
        date: editingSession.date || '',
        revenue: expectedRev,
        expenses: sessionExpenseItems
      });

      setModal('none');
      setEditingSession(null);
      showToast('تم تحديث السجل بنجاح');
    } catch (error) {
      handleFirestoreError(error, OperationType.UPDATE, path);
    }
  };

  const handleDeleteSession = async (sessionId: string) => {
    if (!user) return;
    const path = `users/${user.uid}/sessions/${sessionId}`;
    const transactionPath = `users/${user.uid}/transactions`;
    try {
      await deleteDoc(doc(db, path));
      
      // Also delete related financial transactions
      const q = query(collection(db, transactionPath), where("sessionId", "==", sessionId));
      const querySnapshot = await getDocs(q);
      const batch = writeBatch(db);
      querySnapshot.docs.forEach(d => {
        batch.delete(doc(db, transactionPath, d.id));
      });
      await batch.commit();

      showToast('تم حذف السجل والعمليات المالية المرتبطة به بنجاح');
      setModal('none');
      setModalData(null);
    } catch (error) {
      handleFirestoreError(error, OperationType.DELETE, path);
    }
  };

  const handleCopySessionText = (session: Session) => {
    const date = session.date || (session.createdAt?.toDate ? session.createdAt.toDate().toLocaleDateString('ar-EG', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' }) : 'تاريخ غير معروف');
    
    let text = `سجل: ${session.title}\nالتاريخ: ${date}\n\n`;
    
    const early = session.attendees.filter(isAttendeeEarly);
    const late = session.attendees.filter(isAttendeeLate);
    const presentOnly = session.attendees.filter(a => a.status === 'present');
    const present = [...early, ...late, ...presentOnly];
    const absent = session.attendees.filter(a => a.status === 'absent');
    const excused = session.attendees.filter(a => a.status === 'excused');
    const unpaid = session.attendees.filter(a => a.status === 'unpaid');
    const reserveNotCalled = session.attendees.filter(a => a.status === 'reserve_not_called');
    const reserveNotPresent = session.attendees.filter(a => a.status === 'reserve_not_present');
    const pending = session.attendees.filter(a => a.status === 'pending');

    if (present.length > 0) {
      text += `✅ الحضور (${present.length}):\n`;
      early.forEach(a => text += `- ${a.name} (مبكر)${a.rosterRole === 'reserve' ? ' [احتياط]' : ''}\n`);
      late.forEach(a => text += `- ${a.name} (متأخر)${a.rosterRole === 'reserve' ? ' [احتياط]' : ''}\n`);
      text += '\n';
    }
    
    if (reserveNotCalled.length > 0) {
      text += `🔵 احتياط - لم يُستدعَ (${reserveNotCalled.length}):\n`;
      reserveNotCalled.forEach(a => text += `- ${a.name}\n`);
      text += '\n';
    }

    if (reserveNotPresent.length > 0) {
      text += `🟠 احتياط - لم يحضر بعد الاستدعاء (${reserveNotPresent.length}):\n`;
      reserveNotPresent.forEach(a => text += `- ${a.name}\n`);
      text += '\n';
    }
    
    if (excused.length > 0) {
      text += `⏳ المعتذرين (${excused.length}):\n`;
      excused.forEach(a => text += `- ${a.name}\n`);
      text += '\n';
    }

    if (unpaid.length > 0) {
      text += `💰 لم يدفع (${unpaid.length}):\n`;
      unpaid.forEach(a => text += `- ${a.name}\n`);
      text += '\n';
    }

    if (absent.length > 0) {
      text += `❌ الغياب (${absent.length}):\n`;
      absent.forEach(a => text += `- ${a.name}\n`);
      text += '\n';
    }

    if (pending.length > 0) {
      text += `⏸️ قيد الانتظار (${pending.length}):\n`;
      pending.forEach(a => text += `- ${a.name}\n`);
      text += '\n';
    }

    navigator.clipboard.writeText(text).then(() => {
      showToast('تم نسخ السجل كنص بنجاح');
    }).catch(err => {
      console.error('Failed to copy text: ', err);
      showToast('حدث خطأ أثناء نسخ السجل');
    });
  };

  const handleDuplicateSession = async () => {
    if (!user || !modalData) return;
    const sessionToCopy = modalData as Session;
    
    try {
      // 1. Clear current attendees
      const deletePromises = attendees.map(a => deleteDoc(doc(db, `users/${user.uid}/attendees/${a.id}`)));
      await Promise.all(deletePromises);
      
      // 2. Add new attendees from the session
      const addPromises = sessionToCopy.attendees.map(async (a) => {
        const id = crypto.randomUUID();
        const path = `users/${user.uid}/attendees/${id}`;
        
        let player: Player | undefined;
        if (a.playerId) {
          player = players.find(p => p.id === a.playerId && !p.isDeleted);
        }
        
        if (!player) {
          player = players.find(p => p.name === a.name && !p.isDeleted);
          if (!player) {
            const normalizedInput = normalizeArabic(a.name);
            player = players.find(p => normalizeArabic(p.name) === normalizedInput && !p.isDeleted);
          }
        }
        
        let playerId = player?.id;
        if (!player) {
          playerId = crypto.randomUUID();
          await setDoc(doc(db, `users/${user.uid}/players/${playerId}`), {
            name: a.name,
            weeklyDebt: 0,
            monthlyDebt: 0,
            userId: user.uid,
            createdAt: serverTimestamp(),
            pointsProfile: createDefaultPointsProfile(),
            monthlySubscriptions: [],
            subscriptionTrackingMode: 'auto'
          });
        }
        
        const attendeeData: any = {
          name: player ? player.name : a.name,
          status: 'pending',
          userId: user.uid,
          playerId: playerId,
          rosterRole: (a as any).rosterRole || 'main',
          createdAt: serverTimestamp()
        };
        return setDoc(doc(db, path), attendeeData);
      });
      
      await Promise.all(addPromises);
      
      setModal('none');
      setCurrentView('attendance');
      showToast('تم نسخ الأسماء إلى التحضير بنجاح');
    } catch (error) {
      handleFirestoreError(error, OperationType.CREATE, `users/${user.uid}/attendees`);
    }
  };

